import{_ as o,C as e,o as n,c as i,E as a,a2 as l}from"./chunks/framework.Cc8dJFaW.js";const _=JSON.parse('{"title":"待审批请求恢复了，通知配置也跟着回来了吗？","description":"","frontmatter":{"title":"待审批请求恢复了，通知配置也跟着回来了吗？","article_type":"comparative-study","edition":"research-center","research_question":"恢复待审批工作时，请求关联、保存状态与通知配置分别由谁负责？","summary":"对比两家厂商的文档合同与七组内部局部检查，区分请求重发、响应关联和通知配置；它们仍不能代替送达与当前审批权限的实测。","sources":"同日归档的微软人工参与与检查点文档、CrewAI 企业版人工参与文档，以及内部局部检查。","date":"2026-11-20","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261120-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-20-sig-20261120-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-20-sig-20261120-002.md","filePath":"zh/industry/2026-11-20-sig-20261120-002.md","lastUpdated":1795178581000}'),s={name:"zh/industry/2026-11-20-sig-20261120-002.md"};function h(c,t,p,u,f,m){const r=e("ArticleCover"),d=e("ArticleTableScroll");return n(),i("div",null,[a(r,{image:"/assets/covers/daily-2026-11-20-sig-20261120-002-cover.png",kicker:"研究成果",title:"待审批请求恢复了，通知配置也跟着回来了吗？",summary:"对比两家厂商的文档合同与七组内部局部检查，区分请求重发、响应关联和通知配置；它们仍不能代替送达与当前审批权限的实测。",version:"2026-11-20",languageHref:"/en/industry/2026-11-20-sig-20261120-002",languageLabel:"English"}),a(d,{language:"zh"}),t[0]||(t[0]=l('<h1 id="待审批请求恢复了-通知配置也跟着回来了吗" tabindex="-1">待审批请求恢复了，通知配置也跟着回来了吗？ <a class="header-anchor" href="#待审批请求恢复了-通知配置也跟着回来了吗" aria-label="Permalink to &quot;待审批请求恢复了，通知配置也跟着回来了吗？&quot;">​</a></h1><p>一项等待人工审批的任务恢复后，请求编号还在，是否就能继续通知审核人？这不是一次已发生的故障，而是集成验收中应主动设置的检查场景：有的接口会重新发出待处理请求，有的恢复调用却要求重新提供通知地址。本文的判断是，请求恢复、响应关联和通知配置必须分别验收。平台工程师可以带走一张责任表，查清“恢复成功”究竟覆盖了哪一段。</p><h2 id="两份文档-划出了不同的恢复边界" tabindex="-1">两份文档，划出了不同的恢复边界 <a class="header-anchor" href="#两份文档-划出了不同的恢复边界" aria-label="Permalink to &quot;两份文档，划出了不同的恢复边界&quot;">​</a></h2><p>Microsoft Agent Framework（微软智能体框架）的<a href="https://learn.microsoft.com/en-us/agent-framework/workflows/human-in-the-loop" target="_blank" rel="noreferrer">人工参与文档</a>说明：外部响应通过请求标识关联，交给发出请求的执行器处理。其示例把请求标识作为响应映射的键。检查点会保存待处理请求；恢复时，这些请求会再次成为请求事件，也可以在同一次恢复调用中提交响应。</p><p>这回答了“从哪里继续等待、把回答交给谁”。<a href="https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints" target="_blank" rel="noreferrer">检查点文档</a>进一步说明，它保存执行器状态、下一步待处理消息、请求与响应及共享状态。内存存储不提供跨重启持久性；文件或数据库存储承担不同的持久化用途。重新构建的工作流还必须保持拓扑和执行器身份，自定义执行器需要负责保存与恢复自己的状态。这里的拓扑是执行节点及其连接关系，不是部署网络图。</p><p>这些都是官方文档规定的合同，尚不是本次实测的部署行为。特别是，能找到原请求，不等于已经核实回答者仍有权批准它。</p><p>CrewAI（智能体协作框架）的<a href="https://docs.crewai.com/en/learn/human-in-the-loop" target="_blank" rel="noreferrer">人工参与指南</a>讨论了另一条路径：企业版通过网络回调发送执行标识、任务标识和任务输出，暂停等待人工输入；调用方提交反馈与是否批准的字段来恢复执行。指南明确要求，恢复调用再次传入启动时使用的任务、步骤和整体执行通知地址，这些设置不会自动沿用。</p><p>因此，保留执行标识和任务标识，不能替调用方补齐通知配置。这一要求针对指南中的企业版网络回调方式，不能外推到本地人工反馈装饰器，也不能据此声称企业版“没有保存任何状态”。</p><p>两份文档并不矛盾，也不构成可靠性排名。微软说明的是待处理请求如何恢复和重新进入外部交互；另一份指南强调继续通知所需的调用配置。它们使一个通常被笼统称作“人工参与”的功能，显露出不同的责任边界。</p><h2 id="七组局部检查-实际检查到了什么" tabindex="-1">七组局部检查，实际检查到了什么 <a class="header-anchor" href="#七组局部检查-实际检查到了什么" aria-label="Permalink to &quot;七组局部检查，实际检查到了什么&quot;">​</a></h2><p>同日分析阶段执行了两类内部检查。第一类抽取微软文档中的事件收集函数，用合成异步事件替代真实框架事件流；函数保持原样，人工输入仍保留原示例的省略号占位值。第二类依据另一份指南明确列出的要求，检查恢复载荷有没有漏掉通知字段。后者是分析者编写的合同检查器，没有向企业服务发请求。</p><table tabindex="0"><thead><tr><th>检查输入</th><th>实际结果</th><th>结论到哪里为止</th></tr></thead><tbody><tr><td>没有请求事件</td><td>不返回响应映射</td><td>仅覆盖空输入分支</td></tr><tr><td>两个不同请求标识</td><td>保留两个映射条目</td><td>示例能区分这两个键</td></tr><tr><td>同一请求标识重复出现</td><td>只留下一个映射条目</td><td>键相同会合并，不是防重放证明</td></tr><tr><td>同一标识、不同内容</td><td>仍只留下一个映射条目</td><td>示例映射不负责验证内容是否冲突</td></tr><tr><td>指南中的完整恢复载荷</td><td>未缺通知字段</td><td>只检查字段存在</td></tr><tr><td>保留执行与任务标识，删掉全部通知地址</td><td>缺三个通知字段</td><td>对象标识不能补回通知配置</td></tr><tr><td>仅删掉步骤通知地址</td><td>缺一个通知字段</td><td>检查器能定位这一处遗漏</td></tr></tbody></table><p>完整输入、输出、环境、源码片段与局限保存在<a href="/joinwell52/assets/evidence/2026-11-20-sig-20261120-002/probe-evidence.json">局部检查证据</a>。这些数字是四组收集函数检查和三组载荷检查的计数；其中两组重复标识用例的实际输入相同，因此七组不代表七个不同分支，更不能相加成为七项真实重启测试。所有执行结果都来自内部检查，独立厂商文档并没有使它们变成第三方复现。</p><p>一个三秒例子可以解释映射的边界：同一标识先带“偏低”的提示，后带“偏高”的提示，字典仍然只有一个位置。这个结果不意味着框架真的产生了碰撞，也不意味着批准被覆盖；收集函数中的人工回答还只是占位值。它只提示集成方：请求发生标识、内容版本与外部回答之间的关系，不能由一个字典赋值替你判断。</p><h2 id="用一条等待中的任务分配验收责任" tabindex="-1">用一条等待中的任务分配验收责任 <a class="header-anchor" href="#用一条等待中的任务分配验收责任" aria-label="Permalink to &quot;用一条等待中的任务分配验收责任&quot;">​</a></h2><p>下面是建议的集成验收表，不是声称两款产品都已实现的统一协议。贯穿例子是一项输出等待人工审阅、暂停后重新恢复的任务。先明确恢复的输入与负责人，再要求各段交出自己的可核对输出。</p><table tabindex="0"><thead><tr><th>环节与输入</th><th>建议责任主体</th><th>应保留的输出</th><th>单独检查的条件</th></tr></thead><tbody><tr><td>暂停时的任务状态</td><td>应用与持久化组件</td><td>可定位的检查点及待处理请求</td><td>是否使用跨重启存储、自定义状态是否完整</td></tr><tr><td>检查点进入恢复过程</td><td>工作流构建与恢复入口</td><td>兼容身份和拓扑下重新出现的请求</td><td>结构或身份不兼容时如何处理</td></tr><tr><td>请求事件交给外部集成</td><td>事件接入方</td><td>请求发生标识与待审内容的关联</td><td>再次发出是否代表同一次请求，内容变化如何辨认</td></tr><tr><td>恢复调用继续通知</td><td>调用方与通知集成</td><td>必需通知设置及实际发送、接收记录</td><td>地址是否按合同重传，接收是否真正发生</td></tr><tr><td>回答进入任务继续执行</td><td>响应路由与应用授权层</td><td>回答归属、当前审批权及对应动作</td><td>过期、重复、改派或动作变化如何处理</td></tr></tbody></table><p>这张表把“保存了什么”和“由谁继续做什么”放在同一条验收链上。请求记录能告诉恢复入口继续等哪个回答；通知配置告诉集成往哪里发；送达记录才回答外部是否收到。最后一行又是独立的权限问题。不能因为前几行有了记录，就把最后一行勾成通过。</p><p>对使用指南所述企业版回调方式的应用，一个可执行的下一步是：在固定部署版本中建立条件一致、分别暂停的任务实例，保留各自执行与任务标识，一个使用完整配置恢复，另一个使用遗漏配置恢复，记录服务返回、实际发送与接收情况。对使用微软框架的应用，则在固定软件包版本与持久化存储上重启进程，核对重新发出的请求与外部接入记录。两条测试各自回答集成问题，不应把它们混成一场产品竞赛。本文没有执行这些测试。</p><h2 id="显式重传配置-也可能是合理设计" tabindex="-1">显式重传配置，也可能是合理设计 <a class="header-anchor" href="#显式重传配置-也可能是合理设计" aria-label="Permalink to &quot;显式重传配置，也可能是合理设计&quot;">​</a></h2><p>重复发出同一个待处理请求，可能正是让外部接入方重建等待状态的正确做法。同一请求标识合并为一个映射条目，也可能符合预期。它本身既不证明重复通知造成了副作用，也不证明副作用已被消除。</p><p>同样，恢复时显式提供通知地址，可能使调用方能调整接收目的地。这里不能把设计动机当作厂商已经确认的事实；但它足以成为另一种合理解释，阻止我们把“需要重传配置”直接写成产品缺陷。</p><p>不适用的场景也应说清：没有跨进程恢复、没有外部通知的本地同步审阅，不需要照搬整张表。相反，一旦要声称“重启后必达”或“旧批准不能重放”，就需要真实部署、重复响应与权限变化的实验。指南中对审核人分配、权限、升级和服务时限管理的描述仍是厂商陈述，本次没有检查其实现，不能用来填补这些空白。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本次使用的是 2026-11-20 已完成阅读和分析所保存的快照，生产阶段没有补做检索。两家厂商互相独立，但各自只为自己的文档合同提供一手材料；它们没有互相验证实现。内部检查只检查示例函数和载荷形状。文章中的责任表与后续实验安排属于研究综合与建议，不是现有产品能力。</p><ul><li><a href="https://learn.microsoft.com/en-us/agent-framework/workflows/human-in-the-loop" target="_blank" rel="noreferrer">微软：人工参与文档</a>，官方接口与示例说明；归档页面标示更新于 2026-08-25。支持请求关联与恢复时重新发出的描述。</li><li><a href="https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints" target="_blank" rel="noreferrer">微软：检查点文档</a>，官方持久化与恢复指南；本次完整归档对应文档提交 <code>7a2133efae866b0f4639403fd4f9daaffbeea757</code>。文档版本不等于已固定的运行软件版本。</li><li><a href="https://docs.crewai.com/en/learn/human-in-the-loop" target="_blank" rel="noreferrer">智能体协作框架：人工参与指南</a>，官方产品指南；本次未获得明确的企业部署版本。支持恢复时重传通知配置的要求，不承担送达保证的实测证据。</li><li><a href="/joinwell52/assets/evidence/2026-11-20-sig-20261120-002/probe-evidence.json">内部局部检查材料</a>，包含七组输入输出及方法限制。微软完整可运行示例链接在上游跟进中返回未找到；本次没有完整依赖下的框架执行，也没有企业服务端点实验。</li></ul><h2 id="下一次验收-要看到哪条外部记录" tabindex="-1">下一次验收，要看到哪条外部记录 <a class="header-anchor" href="#下一次验收-要看到哪条外部记录" aria-label="Permalink to &quot;下一次验收，要看到哪条外部记录&quot;">​</a></h2><p>现有证据足以要求集成验收分别列出恢复、关联和通知配置；尚不足以宣布任何一款产品恢复后可靠送达或审批安全。下一次最有价值的记录，是一次真实重启前后的同一请求、实际接收回执以及响应处理结果。若审核人被改派或待批动作已改变，还应检查旧回答如何处置。只有把这些记录接起来，才有材料回答“恢复后仍是谁在批准哪一次动作”，而不仅是“任务编号还在不在”。</p>',28))])}const g=o(s,[["render",h]]);export{_ as __pageData,g as default};
